cost={'main_cases':10,'main_view_cells':len(v),'natural_case_request_attempts':sum(int(r['incremental_case_requests']) for r in v if r['case_id'].startswith('N-')),'natural_case_successful_reads':sum(int(r['successful_case_reads']) for r in v if r['case_id'].startswith('N-')),'natural_case_failed_reads':sum(int(r['failed_case_reads']) for r in v if r['case_id'].startswith('N-')),'final_case_audit_extra_requests':1,'selected_case_requests_including_final_audit':29,'selected_case_successes_including_final_audit':26,'moment_selected_html_bytes_only':689109,'main_cases_gaining_exact_loaded_edition':0,'main_cells_confirming_same_run_edition_and_value':0,'execution_audit_shared_month_queries':120,'ci_run_archives_attempted':15,'ci_run_archives_410':13,'ci_run_archives_404':2,'ci_artifact_lists_read':15,'ci_job_log_extra_attempts':4,'candidate_rows':len(c),'meaning':'views expose actual acquired evidence in V0/V1/V2 order; not three fresh executions or randomized information access; current source packages are not historical installations','unmeasured':'connector responses are not measured HTTP bytes; full cost denominator unknown'}
